function validate([mapping, nums]) {
  if (!Array.isArray(mapping) || mapping.length !== 10) return 'mapping must have exactly 10 entries.';
  if (mapping.some(d => !Number.isInteger(d) || d < 0 || d > 9)) return 'Each mapping entry is a digit from 0 to 9.';
  if (new Set(mapping).size !== 10) return 'The mapping entries must all be different.';
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 30000) return 'nums needs 1 to 3 * 10^4 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v >= 1e9)) return 'Each value in nums is from 0 to 10^9 - 1.';
  return null;
}

