function sortJumbled(mapping, nums) {
  const mapValue = (num) => {
    if (num === 0) {
      return mapping[0];
    }
    let result = 0;
    let place = 1;
    while (num > 0) {
      result += mapping[num % 10] * place;
      place *= 10;
      num = Math.floor(num / 10);
    }
    return result;
  };
  const order = nums.map((num, index) => ({ mapped: mapValue(num), index }));
  order.sort((a, b) => a.mapped - b.mapped || a.index - b.index);
  return order.map((entry) => nums[entry.index]);
}

