function sortJumbled(mapping, nums) {
  // Translate through strings, then a stable insertion sort.
  const key = (num) => Number(String(num).split('').map(d => mapping[Number(d)]).join(''));
  const out = [];
  for (const num of nums) {
    let pos = out.length;
    while (pos > 0 && key(out[pos - 1]) > key(num)) pos--;
    out.splice(pos, 0, num);
  }
  return out;
}

